Given a positive integer n, check whether it is a power of 2 or not.Examples: Input : n = 16Output :  trueExplanation: 24 = 16 Input : n = 42Output :  falseExplanation: 42 is not a power of 2Input : n = 1Output : trueExplanation: 20 = 1Try It YourselfTable of ContentUsing Log - O(1) time and O(1) spaceUsing Division and Modulo Operator - O(log n) time and O(1) spaceUsing Count of Set Bits - O(log n) time and O(1) spaceUsing AND Operator - O(1) time and O(1) spaceUsing AND & NOT Operator - O(1) time and O(1) spaceUsing Log - O(1) time and O(1) spaceThe idea is to use the mathematical property that if a number n is a power of 2, then log2(n) will be an integer. We can compute log2(n) and check if it's an integer by comparing if 2 raised to the power of log2(n) equals n. 
            C++

    #include <iostream>
#include <cmath>
using namespace std;

bool isPowerofTwo(int n) {
    if (n <= 0)
        return false;

    // Calculate log base 2 of n
    int logValue = log2(n);

    // Check if log2(n) is an integer
    // and 2^(logn) = n
    return pow(2, logValue) == n;
}

int main() {
    int n = 16;
    if (isPowerofTwo(n)) {
        cout << "true" << endl;
    }
    else {
        cout << "false" << endl;
    }
}


